<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900;display:flex;justify-content:space-between}header a{color:#ffd45c}main{max-width:1400px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}.add{display:flex;gap:10px}.add input{flex:1;font:inherit;padding:13px;border:2px solid #dbe5e8;border-radius:12px}.duration{width:80px;padding:9px;border:2px solid #dbe5e8;border-radius:10px}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:8px}.pill{display:inline-block;background:#d8f4f4;border-radius:999px;padding:7px 12px;margin:8px 5px 0 0;cursor:pointer}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:220px!important;height:220px!important;border:8px solid #fff}.fs{position:fixed;inset:0;z-index:5;background:#123346;color:#fff;padding:24px;overflow:auto}.top{display:flex;justify-content:space-between;align-items:center}.top h1{font-size:clamp(28px,5vw,70px);margin:0}.clock{font-size:clamp(32px,5vw,68px);color:#ffd45c;font-weight:900}.track{max-width:1200px;margin:20px auto;background:#315c69;border:3px solid #83d8d4;border-radius:24px;overflow:hidden}.track svg{width:100%;display:block}.dot-name{font:700 15px system-ui;fill:#10283d}.board{max-width:520px;margin:16px auto;background:#fff;color:#10283d;border-radius:16px;padding:16px}.row{padding:8px;border-bottom:1px solid #ddd}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.add{flex-direction:column}}
</style></head><body><header><span>PATO NA PISTA 🦆</span><a href="/">← Voltar para home</a></header><main id="app"><div class="hero"><div><small>SALA @{{race.code}}</small><h1>Prepare a corrida.</h1><p>@{{race.names.length}} participantes</p></div><div style="font-size:80px">●</div></div><section class="panel"><div class="grid"><div class="full"><label>Cadastre os participantes</label><div class="add"><input v-model="newName" @keyup.enter="addName" placeholder="Digite um nome"><button @click="addName">Cadastrar nome</button></div><div><span v-for="n in race.names" class="pill" @click="removeName(n)">@{{n}} ×</span></div></div><div><label>Duração <input class="duration" type="number" v-model.number="duration" min="5" max="300"> s</label><br><button @click="start">Começar corrida</button></div><div class="qr"><div id="qr"></div><span>Escaneie para entrar<br>@{{joinUrl}}</span></div></div></section><div v-if="show" class="fs"><div class="top"><div><small>🏁 CIRCUITO AO VIVO · @{{race.code}}</small><h1>@{{done?'🏆 Campeão!':'Quem vai ganhar?'}}</h1></div><div><div class="clock">@{{done?'FIM':Math.ceil(left)+'s'}}</div><button @click="show=false">Sair</button></div></div><div class="track"><svg viewBox="0 0 1000 520"><ellipse cx="500" cy="260" rx="350" ry="190" fill="none" stroke="#84d8d1" stroke-width="100"/><ellipse cx="500" cy="260" rx="350" ry="190" fill="none" stroke="#559879" stroke-width="86" stroke-dasharray="16 14"/><g v-for="r in racers" :id="'d'+r.key"><circle r="16" :fill="r.color" stroke="white" stroke-width="3"/><text x="23" y="5" class="dot-name">@{{r.name}}</text></g></svg></div><div class="board"><h2>Placar ao vivo</h2><div v-for="(r,i) in order" class="row">@{{i+1}}º <b>@{{r.name}}</b></div><p>🔥 Primeiro: <b>@{{order[0]?.name}}</b> · 🐌 Último: <b>@{{order[order.length-1]?.name}}</b></p></div><div v-if="done" class="board"><h2>🏆 @{{winner}}</h2><ol><li v-for="r in race.results">@{{r.position}}º — @{{r.name}}</li></ol></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:@json($race??null),newName:'',joinUrl:'',duration:60,show:false,done:false,left:60,racers:[],order:[],winner:'',timer:null,frame:null}},mounted(){this.joinUrl=location.origin+'/join/'+this.race.code;setTimeout(()=>new QRCode(document.getElementById('qr'),{text:this.joinUrl,width:220,height:220}),50)},methods:{async addName(){if(!this.newName.trim())return;const r=await fetch('/api/races/'+this.race.code+'/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:this.newName.trim(),session:'organizer-'+crypto.randomUUID()})});if(r.ok){this.race=await r.json();this.newName=''}else alert((await r.json()).message)},async removeName(n){this.race.names=this.race.names.filter(x=>x!==n);await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.race.names})})},start(){if(this.race.names.length<2)return alert('Cadastre pelo menos 2 participantes.');this.show=true;this.done=false;this.left=this.duration;const colors=['#ff5f56','#ffd60a','#30d158','#64d2ff','#bf5af2','#ff9f0a'];this.racers=this.race.names.map((name,key)=>({name,key,color:colors[key%colors.length],progress:0,phase:Math.random()*6.28,speed:.75+Math.random()*.5}));this.order=[...this.racers];const t0=performance.now(),tick=now=>{const cycle=Math.min(1,(now-t0)/(this.duration*1000));this.racers.forEach(r=>{const wobble=Math.sin(cycle*18+r.phase)*.018*(1-cycle);r.progress=Math.max(0,Math.min(1,cycle*r.speed+wobble));const angle=(r.progress%1)*Math.PI*2-Math.PI/2,x=500+350*Math.cos(angle),y=260+190*Math.sin(angle),el=document.getElementById('d'+r.key);if(el)el.setAttribute('transform','translate('+x+' '+y+')')});this.order=[...this.racers].sort((a,b)=>b.progress-a.progress);if(cycle<1)this.frame=requestAnimationFrame(tick)};this.frame=requestAnimationFrame(tick);this.timer=setInterval(()=>{this.left--;if(this.left<=0)clearInterval(this.timer)},1000);fetch('/api/races/'+this.race.code+'/start',{method:'POST'}).then(r=>r.json()).then(next=>setTimeout(()=>{this.race=next;this.winner=next.results[0].name;this.done=true;clearInterval(this.timer)},this.duration*1000))}}}).mount('#app')</script></body></html>
